  ["shared.previewsamples.see_the_wanted_popup_portrait_nearby_highlight.04e33a"] = "See the wanted popup, portrait, Nearby highlight and nameplate coin. Replay uses your sound preferences.",
  ["shared.previewsamples.portraits_use_your_selected_player_or_your.6ec2ed"] = "Portraits use your selected player, or your character, as a labelled example. This never places a bounty on them. Live alerts come from sightings, including targets, mouseovers and nameplates.",
  ["shared.previewsamples.wanted_board.b69f07"] = "Wanted board",
  ["shared.previewsamples.wanted_cards_and_full_posters.c0244c"] = "Wanted cards and full posters",
  ["shared.previewsamples.click_the_wanted_card_or_view_bounty.b1ae32"] = "Click the wanted card or View bounty to inspect each contributor, their terms, funding and expiry. Refresh demonstrates a disabled button and loader while sample rewards arrive.",
  ["shared.previewsamples.start_tracking_adds_a_target_to_my.e9b443"] = "Start tracking adds a target to My bounties. After a detected kill, View report opens its status. Posters put the target and reward first, use the parchment width for details and scroll when needed. Unavailable portraits are labelled.",
  ["shared.previewsamples.create_terms.1ea507"] = "Create & terms",
  ["shared.previewsamples.build_a_sample_bounty.01af6d"] = "Build a sample bounty",
  ["shared.previewsamples.three_steps_target_reward_review_nothing_is.cc55e8"] = "Three steps: Target, Reward, Review. Nothing is saved until the final confirmation. One kill with any finish is the default.",
  ["shared.previewsamples.save_returns_to_the_tour_sharing_is.631c62"] = "Save returns to the tour. Sharing is optional. Private tracking can use zero gold; shared rewards need a positive amount and an expiry. Preferred finishes require the poster's review. No live reward is created.",
  ["shared.previewsamples.use_gold_across_your_characters.423446"] = "Use gold across your characters",
  ["shared.previewsamples.see_a_sample_wallet_and_the_bag.2652f4"] = "See a sample wallet and the bag gold tooltip. Try both switches, then enter a reward greater than the available amount in Create & terms.",
  ["shared.previewsamples.account_tracking_is_on_by_default_requiring.faa230"] = "Account tracking is on by default. Requiring enough gold is off by default: an over-budget reward warns but can be created. Balances are scoped to this realm or Forever realmset. Alt balances update when you log in; payment and transfers remain manual.",
  ["shared.previewsamples.guild_approval.d5172b"] = "Guild approval",
  ["shared.previewsamples.submit_and_approve_a_guild_bounty.93c32d"] = "Submit and approve a guild bounty",
  ["shared.previewsamples.try_awaiting_approval_officer_approval_and_rejection.1aed32"] = "Try awaiting approval, officer approval and rejection, then inspect the resulting wanted card. These roles are available in the tour even without a guild.",
  ["shared.previewsamples.approved_guild_rewards_can_show_a_new.36cbe4"] = "Approved guild rewards can show a NEW BOUNTY poster. This announces a reward, not a sighting. Sharing one reward with both guild and global boards does not create a second payment obligation. On Forever, community rewards synchronize only with members of your ruleset.",
  ["shared.previewsamples.shared_arrivals.7e4e7c"] = "Shared arrivals",
  ["shared.previewsamples.a_bounty_matches_your_filters.542556"] = "A bounty matches your filters",
  ["shared.previewsamples.use_start_tracking_or_ignore_on_the.ac8ad1"] = "Use Start tracking or Ignore on the incoming poster. Try sample alert settings and funding states. This target has not been spotted.",
  ["shared.previewsamples.the_notification_minimum_counts_rewards_with_current.7ea6f7"] = "The notification minimum counts rewards with current available-funds reports. Imported, stale or unfunded offers remain distinguishable. Tracking pledges no gold; ignoring silences the target's bounty and sighting alerts.",
  ["shared.previewsamples.grow_a_bounty_s_pot.fc063b"] = "Grow a bounty's pot",
  ["shared.previewsamples.add_a_sample_contribution_review_the_original.3e1e7c"] = "Add a sample contribution, review the original poster's conditions and see the combined reward update.",
  ["shared.previewsamples.accepting_the_terms_means_the_original_poster.cb648e"] = "Accepting the terms means the original poster decides whether a claim qualifies. Contributors owe their amounts to the same accepted hunter. Gold is not held or transferred by the addon.",
  ["shared.previewsamples.share_import.d10b63"] = "Share & import",
  ["shared.previewsamples.copy_a_bounty_link_and_review_an.e6954f"] = "Copy a bounty link and review an import",
  ["shared.previewsamples.sharing_outside_the_addon_is_optional_copy.b960a6"] = "Sharing outside the addon is optional. Copy a global, guild or private bounty link, then review a sample import.",
  ["shared.previewsamples.choose_select_link_to_copy_press_ctrl.75c0bf"] = "Choose Select link to copy, press Ctrl+C and send the bounty link. The recipient chooses Import bounty. Share in chat is available for private and group bounties. Discord channel opens the shared board destination separately. Tour links are deliberately invalid outside the tour.",
  ["shared.previewsamples.kills_reports.48e18a"] = "Kills & reports",
  ["shared.previewsamples.detected_kills_create_reports_automatically.0ec7e1"] = "Detected kills create reports automatically",
  ["shared.previewsamples.use_view_sample_report_to_follow_review.4dce46"] = "Use View sample report to follow review. Try repeated kills and screenshot success, failure or retry. Copying proof is optional.",
  ["shared.previewsamples.readable_killing_blows_are_confirmed_locally_named.83de2e"] = "Readable killing blows are confirmed locally. Named honor credit may include assists. A screenshot checkmark confirms only the image was saved. Reward approval and payment remain separate; manual reporting is for missed detections. This tour takes no screenshots.",
  ["shared.previewsamples.follow_reports_through_review_and_payment.7bf30e"] = "Follow reports through review and payment",
  ["shared.previewsamples.browse_hunter_and_poster_examples_awaiting_review.ee1784"] = "Browse hunter and poster examples: awaiting review, approved, paid and rejected. Try Approve, Reject and Mark paid as the sample poster.",
  ["shared.previewsamples.hunters_cannot_approve_their_own_reports_the.8e822e"] = "Hunters cannot approve their own reports. The poster reviews evidence and manually pays through the game, then records that payment. Repeated kills can count toward a multi-kill goal, without paying twice for the same reward.",
  ["shared.previewsamples.review_enemies_suggested_by_death_reports.470074"] = "Review enemies suggested by death reports",
  ["shared.previewsamples.inspect_sample_reports_review_a_prefilled_bounty.a7057d"] = "Inspect sample reports, review a prefilled bounty, dismiss the suggestion or ignore the enemy.",
  ["shared.previewsamples.suggestions_combine_your_deaths_and_participating_guild.4596f6"] = "Suggestions combine your deaths and participating guild reports within the configured window. They are leads to review, not server-verified kill proof. Nothing is posted until you choose an audience and save.",
